int inside(int r, int c) {
    return r >= 0 && r < N && c >= 0 && c < N;
}

int count_dir(int r, int c, char me, char opp, int d) {
    int nr = r + dr[d], nc = c + dc[d];
    int cnt = 0;
    while (inside(nr, nc) && board[nr][nc] == opp) {
        cnt++;
        nr += dr[d];
        nc += dc[d];
    }
    if (cnt > 0 && inside(nr, nc) && board[nr][nc] == me) return cnt;
    return 0;
}

int total_flip(int r, int c, char me, char opp) {
    if (board[r][c] != '.') return 0;
    int sum = 0;
    for (int d = 0; d < 8; d++) sum += count_dir(r, c, me, opp, d);
    return sum;
}

void apply_move(int r, int c, char me, char opp) {
    board[r][c] = me;
    for (int d = 0; d < 8; d++) {
        int cnt = count_dir(r, c, me, opp, d);
        int nr = r + dr[d], nc = c + dc[d];
        for (int k = 0; k < cnt; k++) {
            board[nr][nc] = me;
            nr += dr[d];
            nc += dc[d];
        }
    }
}

int find_best_move(char me, char opp, int *br, int *bc) {
    int best = 0;
    int found = 0;
    for (int r = 0; r < N; r++) {
        for (int c = 0; c < N; c++) {
            int val = total_flip(r, c, me, opp);
            if (val == 0) continue;
            if (!found || val > best) {
                best = val;
                *br = r;
                *bc = c;
                found = 1;
            } else if (val == best) {
                if (me == 'C') {
                    if (r > *br || (r == *br && c > *bc)) {
                        *br = r;
                        *bc = c;
                    }
                } else { /* me == 'M' */
                    if (r < *br || (r == *br && c < *bc)) {
                        *br = r;
                        *bc = c;
                    }
                }
            }
        }
    }
    return found;
}

