    if (cntC == cntM) turn = 0;
    else if (cntC > cntM) turn = 1;
    else turn = 0;

    while (true) {
        char player = (turn == 0) ? 'C' : 'M';
        char opponent = (player == 'C') ? 'M' : 'C';

        int bestFlips = 0;
        vector<pair<int,int>> candidates;

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (board[i][j] != '.') continue;
                int flips = countFlips(i, j, player);
                if (flips > 0) {
                    if (flips > bestFlips) {
