                        candidates.push_back({i, j});
                    } else if (flips == bestFlips) {
                        candidates.push_back({i, j});
                    }
                }
            }
        }

        if (candidates.empty()) {
            // No moves for current player; game ends if both pass consecutively?
            // Actually if one passes, the other keeps playing until no moves possible.
            // We need to check if opponent can move.
            bool oppCanMove = false;
            for (int i = 0; i < N && !oppCanMove; i++) {
                for (int j = 0; j < N && !oppCanMove; j++) {
                    if (board[i][j] == '.' && countFlips(i, j, opponent) > 0) {
                        oppCanMove = true;
                    }
                }
