            sort(candidates.begin(), candidates.end(), [](auto &a, auto &b) {
                if (a.first != b.first) return a.first > b.first; // lower row (higher index)
                return a.second > b.second; // more right (higher column)
            });
        } else {
            // Mami: higher rows, then more left columns
            sort(candidates.begin(), candidates.end(), [](auto &a, auto &b) {
                if (a.first != b.first) return a.first < b.first; // higher row (lower index)
                return a.second < b.second; // more left (lower column)
            });
        }
        chosen = candidates[0];
        applyFlips(chosen.first, chosen.second, player);
        turn ^= 1;
    }

    // Output final board
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            cout << board[i][j];
        }
        cout << "\n";
    }

    return 0;
}

