        nc += dc[d];
    }
    if (cnt > 0 && inb(nr, nc) && b[nr][nc] == me) return cnt;
    return 0;
}

int countFlips(const Board& b, int r, int c, char me) {
    if (b[r][c] != '.') return 0;
    char opp = (me == 'C' ? 'M' : 'C');
    int total = 0;
    for (int d = 0; d < 8; d++) total += countFlipsDir(b, r, c, d, me, opp);
    return total;
}

void applyMove(Board& b, int r, int c, char me) {
    char opp = (me == 'C' ? 'M' : 'C');
    b[r][c] = me;
    for (int d = 0; d < 8; d++) {
        int flips = countFlipsDir(b, r, c, d, me, opp);
        int nr = r + dr[d], nc = c + dc[d];
        for (int k = 0; k < flips; k++) {
            b[nr][nc] = me;
            nr += dr[d];
            nc += dc[d];
        }
    }
}

bool betterForMami(int r1, int c1, int r2, int c2) {
    if (r1 != r2) return r1 < r2;   // higher row
    return c1 < c2;                 // more left
}

bool betterForCharlotte(int r1, int c1, int r2, int c2) {
    if (r1 != r2) return r1 > r2;   // lower row
    return c1 > c2;                 // more right
}

bool chooseMove(const Board& b, char me, int& br, int& bc) {
    int best = 0;
    bool found = false;
    for (int r = 0; r < N; r++) {
        for (int c = 0; c < N; c++) {
            int flips = countFlips(b, r, c, me);
            if (flips == 0) continue;
            if (!found || flips > best) {
                found = true;
                best = flips;
                br = r; bc = c;
            } else if (flips == best) {
                if (me == 'M') {
                    if (betterForMami(r, c, br, bc)) {
                        br = r; bc = c;
                    }
                } else {
                    if (betterForCharlotte(r, c, br, bc)) {
                        br = r; bc = c;
                    }
                }
            }
        }
    }
    return found;
}

