    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    Board board(8);
    for (int i = 0; i < 8; i++) cin >> board[i];

    // Charlotte (C) starts, then Mami (M), alternating.
    char turn = 'C';
    int consecutivePasses = 0;

    while (consecutivePasses < 2) {
        int r = -1, c = -1;
        if (chooseMove(board, turn, r, c)) {
            applyMove(board, r, c, turn);
            consecutivePasses = 0;
        } else {
            consecutivePasses++;
        }
        turn = (turn == 'C' ? 'M' : 'C');
    }

    for (int i = 0; i < 8; i++) {
        cout << board[i] << '\n';
    }
    return 0;
}

