public class CookieGame {
    static final int N = 8;
    static char[][] board = new char[N][N];
    // Directions: up, down, left, right, and four diagonals
    static final int[] dr = {-1, 1, 0, 0, -1, -1, 1, 1};
    static final int[] dc = {0, 0, -1, 1, -1, 1, -1, 1};

    // Represents a move with its score and position
    static class Move implements Comparable<Move> {
        int r, c;
        int score;
        char type; // 'C' for Charlotte (cheese), 'M' for Mami (chocolate)

        Move(int r, int c, int score, char type) {
            this.r = r;
            this.c = c;
            this.score = score;
            this.type = type;
        }

        // For Charlotte: lower row preferred, if tied more right column
        // For Mami: higher row preferred, if tied more left column
        public int compareTo(Move other) {
            if (this.score != other.score) return other.score - this.score; // higher score first
            if (this.type == 'C') {
                // Charlotte: lower row (higher index), more right column (higher index)
                if (this.r != other.r) return other.r - this.r;
                return other.c - this.c;
            } else {
                // Mami: higher row (lower index), more left column (lower index)
                if (this.r != other.r) return this.r - other.r;
                return this.c - other.c;
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        for (int i = 0; i < N; i++) {
            String line = sc.nextLine().trim();
            // Replace any whitespace if present
            if (line.contains(" ")) {
                line = line.replaceAll("\\s+", "");
            }
            board[i] = line.toCharArray();
        }

        boolean changed = true;
        boolean charlotteTurn = true; // Charlotte starts? Problem says Candy Witch places cheese cookies first? 
        // Actually: "The Candy Witch places cheese cookies, while Mami Tomoe places chocolate cookies alternately."
        // No explicit who goes first, but from context and typical problems, Charlotte (Candy Witch) goes first.
        // We'll determine first player by checking if any move possible for Charlotte; if not, then Mami.
        // But to be safe, we can just start with Charlotte's turn and if no move, switch.

        // Let's check if initial board has any possible move for Charlotte
        // Actually we'll just start with Charlotte and if no move, switch to Mami, alternating.

        while (true) {
            Move bestMove = null;
            char currentType = charlotteTurn ? 'C' : 'M';
            char opponentType = charlotteTurn ? 'M' : 'C';

            // Find all possible moves
            for (int r = 0; r < N; r++) {
                for (int c = 0; c < N; c++) {
                    if (board[r][c] != '.') continue;
                    int score = computeScore(r, c, currentType, opponentType);
                    if (score > 0) {
                        Move move = new Move(r, c, score, currentType);
                        if (bestMove == null || move.compareTo(bestMove) < 0) {
                            bestMove = move;
                        }
                    }
                }
            }

            if (bestMove == null) {
                // No move for current player, try switching
                charlotteTurn = !charlotteTurn;
                currentType = charlotteTurn ? 'C' : 'M';
                opponentType = charlotteTurn ? 'M' : 'C';

                bestMove = null;
                for (int r = 0; r < N; r++) {
                    for (int c = 0; c < N; c++) {
                        if (board[r][c] != '.') continue;
                        int score = computeScore(r, c, currentType, opponentType);
                        if (score > 0) {
                            Move move = new Move(r, c, score, currentType);
                            if (bestMove == null || move.compareTo(bestMove) < 0) {
                                bestMove = move;
                            }
                        }
                    }
                }

                if (bestMove == null) {
                    break; // no one can move
                }
            }

            // Apply the best move
            applyMove(bestMove.r, bestMove.c, bestMove.type, 
                      bestMove.type == 'C' ? 'M' : 'C');
            // Switch turns
            charlotteTurn = !charlotteTurn;
        }

        // Output final board
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                System.out.print(board[i][j]);
            }
            System.out.println();
        }
    }

    static int computeScore(int r, int c, char myType, char opponentType) {
        int total = 0;
        for (int d = 0; d < 8; d++) {
            int nr = r + dr[d];
            int nc = c + dc[d];
            int count = 0;
            // Walk in direction until we hit a boundary or a non-opponent cell
            while (nr >= 0 && nr < N && nc >= 0 && nc < N && board[nr][nc] == opponentType) {
                count++;
                nr += dr[d];
                nc += dc[d];
            }
            // We need to end with one of our own cookies
            if (count > 0 && nr >= 0 && nr < N && nc >= 0 && nc < N && board[nr][nc] == myType) {
                total += count;
            }
        }
        return total;
    }

    static void applyMove(int r, int c, char myType, char opponentType) {
        board[r][c] = myType;
        for (int d = 0; d < 8; d++) {
            int nr = r + dr[d];
            int nc = c + dc[d];
            int count = 0;
            while (nr >= 0 && nr < N && nc >= 0 && nc < N && board[nr][nc] == opponentType) {
                count++;
                nr += dr[d];
                nc += dc[d];
            }
            if (count > 0 && nr >= 0 && nr < N && nc >= 0 && nc < N && board[nr][nc] == myType) {
                // Flip all opponent cookies in between
                nr = r + dr[d];
                nc = c + dc[d];
                for (int i = 0; i < count; i++) {
                    board[nr][nc] = myType;
                    nr += dr[d];
                    nc += dc[d];
                }
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final int N = 8;
    static char[][] board = new char[N][N];

    // Directions: UL, U, UR, L, R, DL, D, DR
    static int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    static int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};

    static class Move {
        int r, c, flips;
        List<int[]> toFlip;

        Move(int r, int c, int flips, List<int[]> toFlip) {
            this.r = r;
            this.c = c;
            this.flips = flips;
            this.toFlip = toFlip;
        }
    }

    static boolean inBounds(int r, int c) {
        return 0 <= r && r < N && 0 <= c && c < N;
    }

    static Move bestMove(char player) {
        char opp = (player == 'C') ? 'M' : 'C';
        Move best = null;

        for (int r = 0; r < N; r++) {
            for (int c = 0; c < N; c++) {
                if (board[r][c] != '.') continue;

                List<int[]> allFlips = new ArrayList<>();
                int total = 0;

                for (int d = 0; d < 8; d++) {
                    int nr = r + dr[d], nc = c + dc[d];
                    List<int[]> cur = new ArrayList<>();

                    while (inBounds(nr, nc) && board[nr][nc] == opp) {
                        cur.add(new int[]{nr, nc});
                        nr += dr[d];
                        nc += dc[d];
                    }

                    if (!cur.isEmpty() && inBounds(nr, nc) && board[nr][nc] == player) {
                        allFlips.addAll(cur);
                        total += cur.size();
                    }
                }

                if (total == 0) continue;

                Move cand = new Move(r, c, total, allFlips);
                if (best == null || better(cand, best, player)) {
                    best = cand;
                }
            }
        }
        return best;
    }

    static boolean better(Move a, Move b, char player) {
        if (a.flips != b.flips) return a.flips > b.flips;

        if (player == 'M') {
            if (a.r != b.r) return a.r < b.r; // higher row
            return a.c < b.c;                 // more left
        } else {
            if (a.r != b.r) return a.r > b.r; // lower row
            return a.c > b.c;                 // more right
        }
    }

    static void applyMove(Move m, char player) {
        board[m.r][m.c] = player;
        for (int[] p : m.toFlip) {
            board[p[0]][p[1]] = player;
        }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        for (int i = 0; i < N; i++) {
            String s = br.readLine();
            while (s != null && s.length() < N) s += " ";
            for (int j = 0; j < N; j++) {
                char ch = s.charAt(j);
                if (ch == 'o' || ch == 'O' || ch == 'C' || ch == 'c') board[i][j] = 'C';
                else if (ch == 'x' || ch == 'X' || ch == 'M' || ch == 'm') board[i][j] = 'M';
                else board[i][j] = '.';
            }
        }

        char turn = 'C'; // Candy Witch starts
        int consecutivePasses = 0;

        while (consecutivePasses < 2) {
            Move mv = bestMove(turn);
            if (mv == null) {
                consecutivePasses++;
            } else {
                applyMove(mv, turn);
                consecutivePasses = 0;
            }
            turn = (turn == 'C') ? 'M' : 'C';
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (board[i][j] == 'C') sb.append('o');
                else if (board[i][j] == 'M') sb.append('x');
                else sb.append('.');
            }
            sb.append('\n');
        }
        System.out.print(sb.toString());
    }
}
